import { test, expect } from '@playwright/test';

test.describe('Data Table Responsive Stacking', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-table');
  });

  test('should stack data table rows vertically on small screens', async ({ page }) => {
    // Set viewport to small screen size
    await page.setViewportSize({ width: 375, height: 800 });

    // Verify table container is visible
    const tableContainer = page.getByRole('region', { name: /data table/i });
    await expect(tableContainer).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /data table/i });
    await expect(tableHeader).toBeVisible();

    // Verify first row is visible
    const firstRow = page.getByRole('row', { name: /john doe/i });
    await expect(firstRow).toBeVisible();

    // Verify first row contains all expected data cells
    const firstCell = page.getByRole('cell', { name: /john doe/i });
    await expect(firstCell).toBeVisible();
    const firstCellAge = page.getByRole('cell', { name: /35/i });
    await expect(firstCellAge).toBeVisible();
    const firstCellEmail = page.getByRole('cell', { name: /john@example.com/i });
    await expect(firstCellEmail).toBeVisible();

    // Verify table is stacked vertically (rows are full width)
    const rowElements = page.locator('[data-testid="table-row"]');
    const rowCount = await rowElements.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify each row takes up full width
    for (let i = 0; i < rowCount; i++) {
      const row = rowElements.nth(i);
      const rowWidth = await row.evaluate((el) => el.offsetWidth);
      expect(rowWidth).toBe(window.innerWidth);
    }

    // Verify table is not using horizontal scroll
    const scrollBar = page.locator('[data-testid="table-scroll-bar"]');
    await expect(scrollBar).not.toBeVisible();
  });

  test('should display data table in responsive stacked format on small screens', async ({ page }) => {
    // Set viewport to small screen size
    await page.setViewportSize({ width: 375, height: 800 });

    // Verify table container is visible
    const tableContainer = page.getByRole('region', { name: /data table/i });
    await expect(tableContainer).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /data table/i });
    await expect(tableHeader).toBeVisible();

    // Verify first row is visible and contains all data
    const firstRow = page.getByRole('row', { name: /john doe/i });
    await expect(firstRow).toBeVisible();

    // Verify all data cells are visible and not truncated
    const allCells = page.getByRole('cell');
    const cellCount = await allCells.count();
    expect(cellCount).toBeGreaterThan(0);

    // Verify each cell has full content
    for (let i = 0; i < cellCount; i++) {
      const cell = allCells.nth(i);
      const cellText = await cell.textContent();
      expect(cellText).not.toContain('...');
    }

    // Verify table is not horizontally scrollable
    const scrollBar = page.locator('[data-testid="table-scroll-bar"]');
    await expect(scrollBar).not.toBeVisible();

    // Verify table is not using horizontal overflow
    const tableElement = page.locator('[data-testid="data-table"]');
    const tableWidth = await tableElement.evaluate((el) => el.offsetWidth);
    expect(tableWidth).toBeLessThanOrEqual(window.innerWidth);
  });
});
